400	    private int namesakeCount(Owner owner) {
401	        String firstName = owner.getFirstName();
402	        String lastName = owner.getLastName();
403	        int count = 0;
404	        for (Owner existing : this.clinicService.findAllOwners()) {
405	            if (firstName != null && lastName != null
406	                && firstName.equalsIgnoreCase(existing.getFirstName())
407	                && lastName.equalsIgnoreCase(existing.getLastName())) {
408	                count++;
409	            }
410	        }
411	        return count;
412	    }
