564	    /**
565	     * The {@code Idempotency-Key} header of the request currently being handled, or {@code null} when
566	     * the header is absent, blank or no servlet request is bound to the calling thread. The generated
567	     * {@link OwnersApi#addOwner} signature carries no header parameter, so it is read from the bound
568	     * request context.
569	     */
570	    private static String currentIdempotencyKey() {
571	        org.springframework.web.context.request.RequestAttributes attrs =
572	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
573	        if (attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs) {
574	            String key = servletAttrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
575	            if (key != null && !key.isBlank()) {
576	                return key;
577	            }
578	        }
579	        return null;
580	    }
